(async () => {
  const out = { path: location.pathname };
  out.title = document.querySelector('.pjx-title')?.textContent || null;
  out.newButton = !!document.querySelector('.pjx-btn-primary');
  out.formOpen = !!document.querySelector('.pjx-create');
  out.formInputs = document.querySelectorAll('.pjx-input').length;
  out.cards = document.querySelectorAll('.pjx-card').length;
  out.firstCard = (document.querySelector('.pjx-card')?.innerText || '').replace(/\s+/g, ' ');
  return JSON.stringify(out);
})()
